#!/bin/sh
# check_replay_goldens.sh -- the Python-free oracle for the native decode path.
#
# For every row of goldens/MANIFEST.tsv: decompress the committed capture,
# check its SHA-256 against the manifest, replay it through the NATIVE path
# with celldiag_replay_ndjson, and diff the canonical output against the golden
# the bridge produced. By default the replay names NO nativedecode= option, so
# it measures the shipping default (nativedecode=only), and
# then nothing here runs Python. The goldens are generated by
# celltools/celldiag_goldens.py, which is dev-only.
#
# The golden BODIES live beside the captures, in $CELL_CAPTURES/goldens/, and are
# not in this tree: they carry bench coordinates and the cell identities of a
# known site, as the captures do. This tree commits only their pins
# (goldens/MANIFEST.tsv); a body that does not hash to its pin fails, so a
# golden cannot change without a commit here.
#
# goldens/KNOWN_DIVERGENCE.tsv lists golden rows the native path is KNOWN to get
# wrong, each against the issue that fixes it. It is strict in both directions,
# like diagspec's THAW_DEBT ledger: an unlisted differing row fails,
# and so does a listed row that now matches. Delete the line when the fix
# lands. The ledger may only shrink.
#
# Environment:
#   CELL_CAPTURES            capture directory (required to measure anything)
#   CELL_CAPTURES_REQUIRED=1 an unset/absent corpus FAILS instead of skipping
#   CELLDIAG_NATIVE_BIN      the NATIVE=1 binary (default ./kismet_cap_cell_diag,
#                            which must then have been built NATIVE=1)
#   REPLAY_NDJSON            the driver (default ./celldiag_replay_ndjson)
#   CELLDIAG_NATIVEDECODE    the native mode replayed:
#                              default  (the default) NO nativedecode= option:
#                                       the binary's own default, which must
#                                       report the helper-less nativedecode=only
#                                       (a binary whose default is anything else
#                                       fails here) and is then judged as `only`
#                              only     helper-less, named explicitly
#                              on       the native legs render beside a running
#                                       bridge (this one spawns Python)
#                            All three must match the goldens.
#
# Exit 0 pass (or skipped with a banner), 1 fail.

set -u
here=$(cd "$(dirname "$0")" && pwd)
pins="$here/goldens"
manifest="$pins/MANIFEST.tsv"
ledger="$pins/KNOWN_DIVERGENCE.tsv"
driver="${REPLAY_NDJSON:-$here/celldiag_replay_ndjson}"
bin="${CELLDIAG_NATIVE_BIN:-$here/kismet_cap_cell_diag}"
imei=000000000000000
nativedecode="${CELLDIAG_NATIVEDECODE:-default}"
case "$nativedecode" in
    default) option=""; judged=only ;;
    on|only) option=",nativedecode=$nativedecode"; judged=$nativedecode ;;
    *) echo "FAIL: CELLDIAG_NATIVEDECODE=$nativedecode (accepted: default, on, only)"; exit 1 ;;
esac

fail=0
failmsg() { echo "  FAIL $*"; fail=$((fail + 1)); }

skip_or_fail() {
    if [ "${CELL_CAPTURES_REQUIRED:-0}" = 1 ]; then
        echo "FAIL: $* (CELL_CAPTURES_REQUIRED=1)"
        exit 1
    fi
    echo "!!! replay goldens NOT CHECKED: $*"
    echo "!!! A pass here says nothing about the native decode path."
    exit 0
}

# The ledger (goldens/) is not part of the public tree: it names captures in the
# private corpus. Without it there is nothing to replay, so skip with the banner
# -- unless a corpus is set, where a missing ledger is a setup error.
if [ ! -f "$manifest" ]; then
    [ -z "${CELL_CAPTURES:-}" ] || { echo "FAIL: CELL_CAPTURES is set but there is no ledger at $manifest"; exit 1; }
    skip_or_fail "no golden ledger at $manifest (it does not ship in the public tree)"
fi
[ -x "$driver" ] || { echo "FAIL: $driver not built (make replay-ndjson)"; exit 1; }
[ -n "${CELL_CAPTURES:-}" ] || skip_or_fail "CELL_CAPTURES is unset; the captures live outside the tree"
[ -d "$CELL_CAPTURES" ] || skip_or_fail "CELL_CAPTURES=$CELL_CAPTURES is not a directory"
gold="$CELL_CAPTURES/goldens"
[ -x "$bin" ] || { echo "FAIL: no binary at $bin"; exit 1; }
if [ -z "${CELLDIAG_NATIVE_BIN:-}" ] && [ "$(cat "$here/.native_mode" 2>/dev/null)" != native ]; then
    echo "FAIL: $bin was not built NATIVE=1 (.native_mode = $(cat "$here/.native_mode" 2>/dev/null || echo absent))."
    echo "      Build it with a plain 'make' (NATIVE=1 is the default), or point CELLDIAG_NATIVE_BIN at a native build."
    exit 1
fi
command -v zstd >/dev/null 2>&1 || { echo "FAIL: zstd not found (the captures are .zst)"; exit 1; }
command -v sha256sum >/dev/null 2>&1 || { echo "FAIL: sha256sum not found"; exit 1; }

tmp=$(mktemp -d "${TMPDIR:-/tmp}/replay_goldens.XXXXXX") || exit 1
trap 'rm -rf "$tmp"' EXIT INT TERM

# Ledger rows: fixture <TAB> stream <TAB> golden line number <TAB> issue <TAB> reason.
listed() {   # $1 fixture, $2 stream, $3 line -> 0 if listed
    [ -f "$ledger" ] && awk -F '\t' -v f="$1" -v s="$2" -v l="$3" \
        '!/^#/ && $1 == f && $2 == s && $3 == l { found = 1 } END { exit !found }' "$ledger"
}

# A stream's golden body, and the native output it is compared with:
#   cell_observation  <fixture>.ndjson         the driver's stdout
#   gps_fix           <fixture>.gps_fix.txt    the "celldiag GPS fix ..." MESSAGE
#                                              lines (the position the binary
#                                              accepted; its geo-tag cache feeds
#                                              the observations' GPS sub-blocks)
#   diag_inventory    <fixture>.diag_inventory.txt  the LAST "celldiag inventory:"
#                                              MESSAGE and the LAST diag_census
#                                              table: the end-of-stream census
#                                              (interim copies are wall-clock paced)
# A fixture in a subdirectory of the corpus names its body with '/' as '__'.
body_of() {   # $1 fixture, $2 stream
    b=$(printf '%s' "$1" | sed 's|/|__|g')
    case "$2" in
        cell_observation) echo "$gold/$b.ndjson" ;;
        gps_fix) echo "$gold/$b.gps_fix.txt" ;;
        diag_inventory) echo "$gold/$b.diag_inventory.txt" ;;
        *) echo "" ;;
    esac
}

# nativedecode=only arms the native census's third state, undecoded_native,
# which a bridge-made golden can never contain. The
# operator's rule for the diag_inventory stream in that mode:
#   * strip ONLY what the state adds, then require byte equality on the rest:
#     the ", N undecoded-native" count and the " undecoded_native[...]" segment
#     of the status message, and the `n` flag of each table row;
#   * an n-only row is a to-do that the native census ranks ahead of healthy rows
#     (diag_inventory.c table_tier), so it can push healthy rows off the
#     24-row table. The rows left after removing n-only rows must therefore be
#     an exact PREFIX of the golden table;
#   * every undecoded_native code, whether a table row or named in the status,
#     must satisfy the state's own definition (capture_cell_diag.c, the
#     native-census branch of native_tap_cb). diaggrok decodes it, so it is in
#     diag_inventory_codes.h, the committed list of codes diaggrok decodes. And
#     no native path consumes it: it is not in kNativeCodes, kIdentityCodes or
#     kNativeGpsCodes in diag_native_decode.cpp. Both lists are read here with
#     grep, so the check does not depend on the 24-row table's size;
#   * where the table can say more, it must agree too. An undecoded row reads
#     `key,count,0,0,0,0,n`: the native census counts the record and nothing
#     else, so decoded/dropped/emitted/enrich_failed are 0. The golden row for
#     the same key must have the same count, decoded > 0 and flag `-` (the
#     bridge decoded it, healthily). A key the golden table lacks is allowed only
#     when that table is FULL and the count is below its smallest healthy count
#     (the row fell off the bridge's table). Anything else is an error.
# No KNOWN_DIVERGENCE rows apply. Prints one line per violation; silent = equal.
diaggrok_codes=$(grep -o '0x[0-9A-Fa-f]\{4\}' "$here/diag_inventory_codes.h" | tr 'a-f' 'A-F' | sed 's/^0X/0x/' | tr '\n' ' ')
native_codes=$(sed -n 's/^const uint16_t k\(Native\|Identity\|NativeGps\)Codes\[\] = {\(.*\)};.*$/\2/p' \
    "$here/diag_native_decode.cpp" | grep -o '0x[0-9A-Fa-f]\{4\}' | tr 'a-f' 'A-F' | sed 's/^0X/0x/' | tr '\n' ' ')

inventory_only_compare() {   # $1 golden body, $2 native output
    awk -v dg="$diaggrok_codes" -v nl="$native_codes" '
    function undecodable(code,   why) {   # "" when code may be undecoded_native
        if (!(code in DG)) return "is not a code diaggrok decodes (diag_inventory_codes.h)"
        if (code in NL) return "has a native path (diag_native_decode.cpp)"
        return ""
    }
    BEGIN {
        n = split(dg, a, " "); for (i = 1; i <= n; i++) DG[a[i]] = 1
        n = split(nl, a, " "); for (i = 1; i <= n; i++) NL[a[i]] = 1
    }
    function table_of(line,   t) {
        t = line; sub(/^census: .*"table":"/, "", t); sub(/".*$/, "", t); return t
    }
    FNR == 1 && NR == 1 { gm = $0; next }
    FNR == 2 && NR == 2 { gt = table_of($0); next }
    FNR == 1 { nm = $0; next }
    FNR == 2 { nt = table_of($0); next }
    END {
        stripped = nm
        gsub(/, [0-9]+ undecoded-native/, "", stripped)
        named = ""
        if (match(stripped, / undecoded_native\[[^]]*\]/)) {
            named = substr(stripped, RSTART + 18, RLENGTH - 19)
            stripped = substr(stripped, 1, RSTART - 1) substr(stripped, RSTART + RLENGTH)
        }
        if (stripped != gm)
            print "inventory message differs beyond the undecoded_native fields: want [" gm "] got [" stripped "]"

        ng = split(gt, G, ";"); full = (ng >= 24)
        minhealthy = -1
        for (i = 1; i <= ng; i++) {
            split(G[i], c, ","); gkey[c[1]] = G[i]; gcode[substr(c[1], 1, 6)] = 1
            if (c[7] == "-" && (minhealthy < 0 || c[2] + 0 < minhealthy)) minhealthy = c[2] + 0
        }
        nn = split(nt, N, ";"); kept = 0
        for (i = 1; i <= nn; i++) {
            k = split(N[i], c, ","); f = c[7]; nonly = 0
            if (index(f, "n")) { gsub(/n/, "", f); if (f == "") { f = "-"; nonly = 1 } }
            row = c[1] "," c[2] "," c[3] "," c[4] "," c[5] "," c[6] "," f
            if (!nonly) {
                kept++
                if (kept > ng || G[kept] != row)
                    print "census row " kept " differs: want [" (kept <= ng ? G[kept] : "(none)") "] got [" row "]"
                continue
            }
            why = undecodable(substr(c[1], 1, 6))
            if (why != "")
                print "undecoded_native row " c[1] " " why
            if (c[3] != "0" || c[4] != "0" || c[5] != "0" || c[6] != "0")
                print "undecoded_native row " c[1] " counts more than the record: [" N[i] "]"
            if (c[1] in gkey) {
                split(gkey[c[1]], g, ",")
                if (g[2] != c[2] || !(g[3] + 0 > 0) || g[7] != "-")
                    print "undecoded_native row " c[1] " disagrees with the bridge row: want count " c[2] " decoded>0 flag - in [" gkey[c[1]] "]"
            } else if (!full) {
                print "undecoded_native row " c[1] " is not in the bridge census table, which is not full"
            } else if (minhealthy >= 0 && c[2] + 0 > minhealthy) {
                print "undecoded_native row " c[1] " (count " c[2] ") would have made the bridge table (min healthy " minhealthy ")"
            }
        }
        if (named != "") {
            sub(/ \+[0-9]+ more$/, "", named)
            m = split(named, C, ", ")
            for (i = 1; i <= m; i++) {
                why = undecodable(C[i])
                if (why != "")
                    print "undecoded_native code " C[i] " (status) " why
            }
        }
    }' "$1" "$2"
}

if [ "$nativedecode" = default ]; then
    echo "replay goldens: native $bin (no nativedecode= option: the binary's default, judged as only)"
else
    echo "replay goldens: native $bin (nativedecode=$nativedecode)"
fi
rows_checked=0
replayed=""          # the fixture whose native outputs are in $tmp
replay_ok=0
while IFS="$(printf '\t')" read -r fixture stream cap_sha gold_sha rows rev; do
    case "$fixture" in ''|'#'*) continue ;; esac
    before=$fail
    g=$(body_of "$fixture" "$stream")
    [ -n "$g" ] || { failmsg "$fixture: unknown stream '$stream' in the manifest"; continue; }

    # One native replay per fixture, shared by its streams (the manifest is
    # sorted, so a fixture's rows are adjacent).
    if [ "$replayed" != "$fixture" ]; then
        replayed=$fixture
        replay_ok=0
        if [ -f "$CELL_CAPTURES/$fixture" ]; then
            cp "$CELL_CAPTURES/$fixture" "$tmp/replay.raw"
        elif [ -f "$CELL_CAPTURES/$fixture.zst" ]; then
            # On stdin: zstd skips a symlinked input named on its command line.
            zstd -dqc < "$CELL_CAPTURES/$fixture.zst" > "$tmp/replay.raw" || { failmsg "$fixture: zstd failed"; continue; }
        else
            if [ "${CELL_CAPTURES_REQUIRED:-0}" = 1 ]; then
                failmsg "$fixture: capture not in $CELL_CAPTURES"
            else
                echo "  skip $fixture: capture not in $CELL_CAPTURES"
            fi
            continue
        fi
        got=$(sha256sum "$tmp/replay.raw" | cut -d' ' -f1)
        [ "$got" = "$cap_sha" ] || { failmsg "$fixture: capture hash $got is not the golden's $cap_sha"; continue; }
        "$driver" "$bin" "celldiag-$imei:replay=$tmp/replay.raw$option" \
            > "$tmp/native.cell_observation" 2> "$tmp/native.err"
        rc=$?
        if [ $rc -ne 0 ]; then
            failmsg "$fixture: native replay exited $rc"
            sed 's/^/        /' "$tmp/native.err" | tail -5
            continue
        fi
        # With no option, the binary chose the mode. Judging it as `only`
        # is right only if `only` is what it ran, which its own report says.
        if [ "$nativedecode" = default ] &&
           ! grep -q '^message: decoder root: none (nativedecode=only' "$tmp/native.err"; then
            failmsg "$fixture: with no nativedecode= option the binary did not run nativedecode=only:"
            grep -m 3 'decoder root' "$tmp/native.err" | sed 's/^/        /'
            continue
        fi
        sed -n 's/^message: \(celldiag GPS fix .*\)$/\1/p' "$tmp/native.err" > "$tmp/native.gps_fix"
        { sed -n 's/^message: \(celldiag inventory: .*\)$/\1/p' "$tmp/native.err" | tail -n 1
          grep '^census: ' "$tmp/native.err" | tail -n 1; } > "$tmp/native.diag_inventory"
        replay_ok=1
    elif [ $replay_ok -ne 1 ]; then
        continue                  # this fixture's replay already failed or skipped
    fi

    # The capture is present, so its golden must be too: a corpus with captures
    # and no goldens is a setup error, not a skip.
    if [ ! -f "$g" ]; then failmsg "$fixture [$stream]: golden body $g missing"; continue; fi
    got=$(sha256sum "$g" | cut -d' ' -f1)
    [ "$got" = "$gold_sha" ] || { failmsg "$fixture [$stream]: golden body $g does not hash to its committed pin"; continue; }

    out="$tmp/native.$stream"
    n=$(wc -l < "$out" | tr -d ' ')
    if [ "$n" != "$rows" ]; then
        failmsg "$fixture [$stream]: native emitted $n rows, the golden has $rows"
        continue
    fi

    if [ "$judged" = only ] && [ "$stream" = diag_inventory ]; then
        inventory_only_compare "$g" "$out" > "$tmp/inv_only"
        if [ -s "$tmp/inv_only" ]; then
            while read -r msg; do failmsg "$fixture [$stream, only]: $msg"; done < "$tmp/inv_only"
        else
            echo "  ok   $fixture [$stream]: equal under the undecoded_native rule (nativedecode=only)"
        fi
        rows_checked=$((rows_checked + rows))
        continue
    fi

    # Row-by-row, so each difference can be held against the ledger.
    paste -d '\n' "$g" "$out" | awk '
        NR % 2 == 1 { want = $0; next }
        { line = NR / 2; if ($0 != want) print line }' > "$tmp/differ"
    bad=0
    while read -r line; do
        if listed "$fixture" "$stream" "$line"; then
            continue
        fi
        failmsg "$fixture [$stream]:$line: native differs from the golden"
        echo "        want: $(sed -n "${line}p" "$g" | cut -c1-300)"
        echo "        got:  $(sed -n "${line}p" "$out" | cut -c1-300)"
        bad=$((bad + 1))
        [ $bad -ge 3 ] && { echo "        (further rows not shown)"; break; }
    done < "$tmp/differ"
    if [ -f "$ledger" ]; then
        awk -F '\t' -v f="$fixture" -v s="$stream" '!/^#/ && $1 == f && $2 == s { print $3 "\t" $4 }' "$ledger" |
        while IFS="$(printf '\t')" read -r line issue; do
            grep -qx "$line" "$tmp/differ" ||
                echo "  FAIL $fixture [$stream]:$line: listed in KNOWN_DIVERGENCE.tsv ($issue) but now MATCHES -- delete its ledger line"
        done > "$tmp/xpass"
        if [ -s "$tmp/xpass" ]; then
            cat "$tmp/xpass"
            fail=$((fail + $(wc -l < "$tmp/xpass")))
        fi
    fi
    known=0
    while read -r line; do listed "$fixture" "$stream" "$line" && known=$((known + 1)); done < "$tmp/differ"
    if [ $fail -eq $before ]; then
        echo "  ok   $fixture [$stream]: $rows rows$( [ $known -gt 0 ] && echo ", $known known divergence(s) (KNOWN_DIVERGENCE.tsv)")"
    fi
    rows_checked=$((rows_checked + rows))
done < "$manifest"

if [ $fail -gt 0 ]; then
    echo "FAIL: $fail replay-golden failure(s)"
    exit 1
fi
[ $rows_checked -gt 0 ] || skip_or_fail "none of the manifest's captures is in $CELL_CAPTURES"
echo "PASS: replay goldens ($rows_checked rows)"
